with recent_accounts as (select *, last_day(opened_date) as opened_date_month_end from accounts where opened_date between '2023-07-01' and '2024-11-01'), status_summary as (select status, avg(balance) as avg_balance, count(distinct balance) as unique_statuss from recent_accounts group by status) select status, avg_balance from status_summary where unique_statuss < 8 order by 1, avg_balance
